{"requirements": [
    {
        "id": 1,
        "text": "The system shall implement a dice-throwing game for three players."
    },
    {
        "id": 2,
        "text": "The system shall initialize each player's points to 0."
    },
    {
        "id": 3,
        "text": "The system shall determine the turn order for the players at the beginning of the game."
    },
    {
        "id": 4,
        "text": "The system shall have each player throw a dice in each turn."
    },
    {
        "id": 5,
        "text": "The system shall add the dice count to the player's points after each turn."
    },
    {
        "id": 6,
        "text": "The system shall print the dice count and the player's points after each turn."
    },
    {
        "id": 7,
        "text": "The system shall end the game after 12 turns."
    },
    {
        "id": 8,
        "text": "The system shall end the game if one player has significantly more points than the others."
    },
    {
        "id": 9,
        "text": "The system shall check if the dice count is 1 and prompt the player to re-roll if so."
    },
    {
        "id": 10,
        "text": "The system shall display a congratulatory message for the winner."
    },
    {
        "id": 11,
        "text": "The system shall assign the point colors red, green, and blue to player 1, player 2, and player 3 respectively."
    },
    {
        "id": 12,
        "text": "The system shall change the point color of a player to purple if their points are sufficient to win."
    },
    {
        "id": 13,
        "text": "The system shall prevent the current player's turn from continuing if they throw a 6."
    },
    {
        "id": 14,
        "text": "The system shall triple the dice count if it is 2, and halve it if it is even."
    },
    {
        "id": 15,
        "text": "The system shall check the players' points at any point in the game and print 'Equality!' if they are equal."
    },
    {
        "id": 16,
        "text": "The system shall display the players' names before the game starts."
    },
    {
        "id": 17,
        "text": "The system shall validate the player names and prompt for a new name if 'Computer' is entered."
    },
    {
        "id": 18,
        "text": "The system shall multiply the dice counts by 2 if the dice count is high."
    },
    {
        "id": 19,
        "text": "The system shall reset a player's points to 0 if they throw the same value multiple times in a row."
    },
    {
        "id": 20,
        "text": "The system shall allow a player to skip their turn."
    },
    {
        "id": 21,
        "text": "The system shall determine the winner of the game after it has ended."
    },
    {
        "id": 22,
        "text": "The system shall not end the game until one player has more points than the others if two players are equal."
    },
    {
        "id": 23,
        "text": "The system shall print the players' points and the winner after a game has ended."
    },
    {
        "id": 24,
        "text": "The system shall declare one player as the winner after the game has ended."
    },
    {
        "id": 25,
        "text": "The system shall order the players in a predetermined way if they decide to play again."
    }
]}
